use strict;
use warnings;

my @defaults = (
    'push: vi.fn(),',    'replace: vi.fn(),',
    'back: vi.fn(),',    'forward: vi.fn(),',
    'refresh: vi.fn(),', 'prefetch: vi.fn(),',
    "bfcacheId: '',",
);
my %is_default = map { $_ => 1 } @defaults;

for my $file (@ARGV) {
    open my $fh, '<', $file or die "$file: $!";
    my $src = do { local $/; <$fh> };
    close $fh;

    my $count = 0;
    $src =~ s{
        (?<indent>[ ]*)vi\.mocked\(useRouter\)\.mockReturnValue\(\{\n
        (?<body>(?:[ ]*[A-Za-z]+[^\n]*\n)+?)
        [ ]*\}\);
    }{
        my ($indent, $body) = ($+{indent}, $+{body});
        my @keep;
        for my $line (split /\n/, $body) {
            my $t = $line; $t =~ s/^\s+//; $t =~ s/\s+$//;
            push @keep, $t unless $is_default{$t};
        }
        $count++;
        my $args = @keep ? '{ ' . join(' ', @keep) . ' }' : '';
        "${indent}vi.mocked(useRouter).mockReturnValue(mockRouter($args));";
    }gex;

    open my $out, '>', $file or die "$file: $!";
    print $out $src;
    close $out;
    print "$file: $count\n";
}

